const body = $('Webhook').first().json.body;
const out = $input.first().json;
let text = '';
if (out.candidates && Array.isArray(out.candidates) && out.candidates[0]) {
  const parts = out.candidates[0].content?.parts || [];
  text = parts.filter(p => p.text).map(p => p.text).join('\n');
}
if (!text && typeof out.message === 'string') text = out.message;
if (!text && out.text) text = out.text;
if (!text && out.output) text = out.output;
return [{json:{session_id: body.sessionId, file_id: body.fileId, file_name: body.fileName, mime_type: body.mimeType, summary: text, extracted_text: text, upload_order: body.uploadOrder||1, char_count: text.length, file_url: body.fileUrl}}];
